/**
 * CHROMIUM-MEASURED RENDERS for the label fuzz test (rule (5) of labels.ts).
 *
 * These are the widths Chromium ACTUALLY DREW — not the estimate's own model —
 * for the fuzz strings generated by {@link generateFuzzStrings} in the label's
 * declared font stack at WEIGHT 700 (the name band's weight). Each value is the
 * MAXIMUM `measureText` width, in tenths of a pixel at a 100 px font, across
 * every font of the stack that resolves on the measurement box (Tahoma,
 * Segoe UI, Arial; `Noto Naskh Arabic` and `Amiri` do not resolve there, so
 * the stack falls through to Tahoma for Arabic). The sweep is the same one that
 * produced {@link MEASURED_EM} in src/domain/labels.ts.
 *
 *   * `FUZZ_PX_S` is the render of the generated string, in generation order.
 *   * `FUZZ_PX_T` is the render of the string AFTER truncation to the label's
 *     own text band (46 mm x TRUNCATE_SAFETY 0.97 at font-size 3.4 mm).
 *
 * THE POOLS ARE BUILT SO THE WORST STRING IS POSSIBLE BY CONSTRUCTION. Earlier
 * rounds drew Arabic from `سشصض` alone, so no pool could EVER produce a name
 * built from the letter nobody had measured (`ط`), and the estimate's under-read
 * stayed invisible for three rounds. Now EVERY Arabic letter in the swept ranges
 * has its own HOMOGENEOUS pool — a run of nothing but that letter — alongside
 * the widest-letter pools for Latin, the Arabic base / supplement / extended-A
 * ranges, the fullwidth forms, digits, spaces and a mixed pool. A per-letter
 * constant that is under its measurement therefore makes one of these pools
 * render wider than the estimate and turns the fuzz RED. A pool built only from
 * the letters already known to be wide could never do that.
 *
 * THE SWEEP: 1722 strings over 253 pools — the six wide pools (caps, lower,
 * arabicWide, digits, spaces, mixed) x 90; the arabicAll / supplement /
 * extendedA / fullwidth range pools x 40; and 243 PER-LETTER homogeneous pools
 * (153 base + 48 supplement + 42 extended-A Arabic letters) x 4.
 *
 * The arrays are keyed by POSITION, and the test regenerates the strings with
 * the same seeded PRNG ({@link FUZZ_SEED}) and checks them against the baked
 * checksums, so a drift in generation is caught loudly.
 */

/** The PRNG seed the sweep used (mulberry32). */
export const FUZZ_SEED = 1592594996;

/** How many strings each WIDE pool produced. */
export const FUZZ_N_PER_POOL = 90;

/** How many homogeneous runs each PER-LETTER pool produced. */
export const FUZZ_N_PER_LETTER = 4;

/** The label's name band: 46 mm x TRUNCATE_SAFETY, at the 3.4 mm name size. */
export const FUZZ_BAND_MM = 46;
export const FUZZ_SAFETY = 0.97;
export const FUZZ_FONT_MM = 3.4;

/** The generated strings, in generation order, must hash to this (FNV-1a). */
export const FUZZ_CHECKSUM_S = "c54591e4";
export const FUZZ_CHECKSUM_T = "a5ad8b10";

/** mulberry32 — the seeded PRNG the sweep used, so the test can regenerate it. */
export function mulberry32(a: number): () => number {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** FNV-1a over the strings, each closed with a newline — the drift guard. */
export function fuzzChecksum(strings: readonly string[]): string {
  let h = 0x811c9dc5;
  // The sweep appended a newline after EVERY string (including the last).
  const joined = strings.map((s) => s + String.fromCharCode(10)).join('');
  for (let i = 0; i < joined.length; i++) {
    h ^= joined.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16);
}

/** Every code point in `[lo, hi]` (inclusive), as a pool of one-char entries. */
function rangePool(lo: number, hi: number): string[] {
  const out: string[] = [];
  for (let cp = lo; cp <= hi; cp++) out.push(String.fromCodePoint(cp));
  return out;
}

/**
 * One HOMOGENEOUS pool per Arabic LETTER in `[lo, hi]`: the pool holds only that
 * letter (tripled, though a single entry suffices), so a homogeneous connected
 * run of that letter is what it draws by construction, and each pool renders
 * {@link FUZZ_N_PER_LETTER} runs. This is the pool that makes the widest form of
 * EVERY letter reachable — not only the four somebody had flagged.
 */
function letterPools(lo: number, hi: number, label: string): ReadonlyArray<readonly [string, readonly string[], number]> {
  const out: Array<readonly [string, readonly string[], number]> = [];
  for (let cp = lo; cp <= hi; cp++) {
    const ch = String.fromCodePoint(cp);
    if (/\p{L}/u.test(ch)) out.push([`${label}-${cp.toString(16)}`, [ch, ch, ch], FUZZ_N_PER_LETTER]);
  }
  return out;
}

/**
 * The pools, in the order the sweep drew from them: `[label, pool, count]`.
 * WIDEST-WEIGHTED, and — for Arabic — PER-LETTER, so the dangerous tail of every
 * script and every letter is in the generated set BY CONSTRUCTION.
 */
export const FUZZ_POOLS: ReadonlyArray<readonly [string, readonly string[], number]> = [
  ['caps', ['W', 'M', 'W', 'M', 'O', 'Q', 'G', 'H', 'D', 'K', 'B', 'V', 'X', 'Y', 'N'], FUZZ_N_PER_POOL],
  ['lower', ['m', 'w', 'm', 'w', 'h', 'b', 'n', 'u', 'd', 'g', 'k', 'q', 'p', 'y'], FUZZ_N_PER_POOL],
  ['arabicWide', ['س', 'ش', 'ص', 'ض'], FUZZ_N_PER_POOL],
  ['digits', rangePool(0x30, 0x39), FUZZ_N_PER_POOL],
  ['spaces', [' ', ' ', 'ا', 'س'], FUZZ_N_PER_POOL],
  ['mixed', ['A', 'B', 'W', 'M', 'm', 'w', 'س', 'ش', 'ص', 'ض', '0', '9', ' '], FUZZ_N_PER_POOL],
  ['arabicAll', rangePool(0x0600, 0x06ff), FUZZ_N_PER_POOL],
  ['supplement', rangePool(0x0750, 0x077f), 40],
  ['extendedA', rangePool(0x08a0, 0x08ff), 40],
  ['fullwidth', rangePool(0xff01, 0xff5e), 40],
  ...letterPools(0x0600, 0x06ff, 'ar'),
  ...letterPools(0x0750, 0x077f, 'sup'),
  ...letterPools(0x08a0, 0x08ff, 'ext'),
];

/** `count` random strings from each pool, in sweep order (see {@link FUZZ_POOLS}). */
export function generateFuzzStrings(): string[] {
  const rnd = mulberry32(FUZZ_SEED);
  const out: string[] = [];
  for (const [, pool, count] of FUZZ_POOLS) {
    for (let i = 0; i < count; i++) {
      const len = 1 + Math.floor(rnd() * 20);
      let s = '';
      for (let j = 0; j < len; j++) s += pool[Math.floor(rnd() * pool.length)];
      out.push(s);
    }
  }
  return out;
}

